import { colors } from '../../tokens/colors.mjs';


/*
 * Physical sidewalk polygons generated by PostGIS.
 *
 * These render underneath the asphalt so the road/sidewalk
 * boundary remains clean even if the polygons overlap by a
 * tiny amount.
 */

export const sidewalkLayers = [
    {
        id: 'sidewalk-surfaces',

        type: 'fill',

        source: 'sidewalk_surfaces',
        'source-layer': 'sidewalk_surfaces',

        minzoom: 15,

        paint: {
            'fill-color': colors.sidewalk,
            'fill-opacity': 1,
            'fill-antialias': true
        }
    }
];